mapper.update:
UPDATE monthly_ticket_season
SET status = 'CLOSING',
    closing_at = #{closingAt},
    version = version + 1
WHERE id = #{seasonId}
  AND status = 'OPEN'
  AND version = #{expectedVersion}
  AND vote_cutoff_at <= #{closingAt}

mapper.insert:
INSERT IGNORE INTO monthly_rank_snapshot
    (season_id, sequence_no, status, cutoff_at)
SELECT id, 1, 'BUILDING', #{cutoffAt}
FROM monthly_ticket_season
WHERE id = #{seasonId}
  AND status = 'CLOSING'

mapper.update:
UPDATE monthly_ticket_season
SET status = 'REVIEW',
    snapshot_id = #{snapshotId},
    review_at = #{reviewAt},
    version = version + 1
WHERE id = #{seasonId}
  AND status = 'CLOSING'
  AND version = #{expectedVersion}
  AND EXISTS (
      SELECT 1
      FROM monthly_rank_snapshot snapshot
      WHERE snapshot.id = #{snapshotId}
        AND snapshot.season_id = #{seasonId}
        AND snapshot.status = 'SEALED'
  )

mapper.select:
SELECT checkpoint
FROM scheduled_job_run
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}
LIMIT 1

mapper.update:
UPDATE scheduled_job_run
SET checkpoint = #{checkpoint},
    processed_count = processed_count + #{processedDelta},
    heartbeat_at = #{heartbeatAt},
    version = version + 1
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}

UPDATE scheduled_job_run
SET status = 'SUCCEEDED',
    heartbeat_at = #{finishedAt},
    finished_at = #{finishedAt},
    error_message = NULL,
    version = version + 1
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}

UPDATE scheduled_job_run
SET status = 'FAILED',
    heartbeat_at = #{finishedAt},
    finished_at = #{finishedAt},
    error_message = #{errorMessage},
    version = version + 1
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}

mapper.select:
SELECT COUNT(*)
FROM monthly_rank_counter
WHERE season_id = #{seasonId}

SELECT COUNT(*)
FROM monthly_rank_entry
WHERE snapshot_id = #{snapshotId}

SELECT source.season_id AS seasonId, source.book_id AS bookId, source.source_tickets AS sourceTickets, COALESCE(counter.total_tickets, 0) AS projectedTickets, source.source_voters AS sourceVoters, COALESCE(counter.distinct_voter_count, 0) AS projectedVoters FROM ( SELECT vote.season_id, vote.book_id, SUM(vote.ticket_count) AS source_tickets, COUNT(DISTINCT vote.user_id) AS source_voters FROM monthly_ticket_vote vote WHERE vote.status = 'VALID'
AND vote.season_id = #{seasonId}
GROUP BY vote.season_id, vote.book_id ) source LEFT JOIN monthly_rank_counter counter ON counter.season_id = source.season_id AND counter.book_id = source.book_id WHERE counter.book_id IS NULL OR counter.total_tickets <> source.source_tickets OR counter.distinct_voter_count <> source.source_voters UNION ALL SELECT counter.season_id AS seasonId, counter.book_id AS bookId, 0 AS sourceTickets, counter.total_tickets AS projectedTickets, 0 AS sourceVoters, counter.distinct_voter_count AS projectedVoters FROM monthly_rank_counter counter LEFT JOIN ( SELECT vote.season_id, vote.book_id, SUM(vote.ticket_count) AS source_tickets, COUNT(DISTINCT vote.user_id) AS source_voters FROM monthly_ticket_vote vote WHERE vote.status = 'VALID'
AND vote.season_id = #{seasonId}
GROUP BY vote.season_id, vote.book_id ) source ON source.season_id = counter.season_id AND source.book_id = counter.book_id WHERE source.book_id IS NULL
AND counter.season_id = #{seasonId}

mapper.update:
UPDATE monthly_ticket_season
SET status = 'FINALIZED',
    finalized_at = #{finalizedAt},
    finalized_by = #{operatorId},
    version = version + 1
WHERE id = #{seasonId}
  AND status = 'REVIEW'
  AND version = #{expectedVersion}
  AND snapshot_id = #{snapshotId}
  AND EXISTS (
      SELECT 1
      FROM monthly_rank_snapshot snapshot
      WHERE snapshot.id = #{snapshotId}
        AND snapshot.season_id = #{seasonId}
        AND snapshot.status = 'SEALED'
  )
